const genericFooter = 'Reply STOP to opt out. Do not send personal health information by text.';
return $input.all().flatMap((item) => {
  const consult = item.json;
  const base = {
    consultId: consult.consultId,
    contactName: consult.contactName,
    contactPhone: consult.contactPhone,
    contactEmail: consult.contactEmail,
    consultAt: consult.consultAt,
    demoOnly: true
  };
  return [
    { json: { ...base, reminderType: '24-hour', message: `Reminder: your introductory consult with Cedar Park Counseling Collective is tomorrow. If you need to reschedule, reply to this message or call the office. ${genericFooter}` } },
    { json: { ...base, reminderType: '2-hour', message: `Reminder: your introductory consult is coming up soon. Please use the confirmed consult channel and contact the office if plans changed. ${genericFooter}` } }
  ];
});
